add_filter( 'post_thumbnail_html', 'perfectpixel_link_featured_images', 20, 2 );

function perfectpixel_link_featured_images( $html, $post_id ) {
	if ( '' === $html || is_admin() || ( is_singular() && get_queried_object_id() === (int) $post_id ) || false !== stripos( $html, '<a ' ) ) {
		return $html;
	}
	return '<a href="' . esc_url( get_permalink( $post_id ) ) . '" aria-hidden="true" tabindex="-1">' . $html . '</a>';
}
